import React, { useEffect, useState } from 'react';
import { Pill } from '../../../ui';
import { contractsApi } from '../../../lib/api/contracts';
import { GENERATED_PILL, proseState, visibleGenerated } from '../../../lib/generatedDocuments';
import { reportError } from '../../../lib/log';
import { card } from './parts';
import { Thumbnail } from './TemplateThumbnail';

// D758 (#1864) — the Templates tab's "Generated by the platform" group: the
// documents the platform builds in code (the seven notices, the Subscription
// Booklet, the Structure of the Fund page and the certificate), each with its
// real page 1 drawn as a specimen. Read-only (decision 3): text is edited on
// the library row, so each row's title opens it in the editor.
//
// Unlike "Not in the catalog", this group is the only place these documents
// are listed, so a failed read draws the header, the Worker's sentence and
// Retry (decision 10). While pending it draws nothing.

const muted = 'text-axal-muted dark:text-[#a29db0]';
const roseLink = 'text-left text-[11px] font-semibold text-[#881337] underline-offset-2 hover:underline dark:text-rose-300';

function ProseRow({ row, onOpen }) {
  const s = proseState(row);
  if (row.missing) {
    return <li className="flex flex-wrap items-center gap-1.5">
      <span className={`font-mono text-[10.5px] ${muted}`}>{row.slug}</span>
      <Pill tone={s.tone}>{s.label}</Pill>
    </li>;
  }
  return <li className="flex flex-wrap items-center gap-1.5">
    <button type="button" className={roseLink} onClick={() => onOpen(row.slug)}>
      {row.part != null ? `Part ${row.part} · ` : ''}{row.title || row.slug}
    </button>
    <Pill tone={s.tone}>{s.label}</Pill>
  </li>;
}

function GeneratedCard({ item, thumbs, onOpen }) {
  return <div data-testid={`generated-card-${item.key}`} className={`${card} flex gap-2.5 p-2.5 dark:border-[#2a2733] dark:bg-[#18161f]`}>
    <Thumbnail thumbs={thumbs} version={item.thumbnail_version} stub={false} title={item.title}
      load={() => contractsApi.generatedThumbnailBlob(item.key, item.thumbnail_version)} />
    <div className="flex min-w-0 flex-1 flex-col gap-1">
      <p className="line-clamp-2 text-[12.5px] font-bold leading-[1.3]">{item.title}</p>
      <p className={`text-[11px] leading-[1.3] ${muted}`}>{item.kind} · {item.party_line}</p>
      <span><Pill tone="info">{GENERATED_PILL}</Pill></span>
      {item.prose?.length
        ? <>
          <p className={`text-[11px] ${muted}`}>Text from the library:</p>
          <ul className="flex flex-col gap-1">{item.prose.map(row => <ProseRow key={row.slug} row={row} onOpen={onOpen} />)}</ul>
        </>
        : <p className={`text-[11px] ${muted}`}>No library text: the platform writes every line.</p>}
      {item.refusal && <p className="text-[11px] font-semibold text-axal-amber-deep dark:text-amber-300">{item.refusal.message}</p>}
    </div>
  </div>;
}

export default function GeneratedDocuments({ q, layer, state, onOpen, thumbs }) {
  const [read, setRead] = useState({ status: 'pending', items: [], error: '' });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let active = true;
    contractsApi.generated().then(r => {
      if (active) setRead({ status: 'ok', items: Array.isArray(r?.items) ? r.items : [], error: '' });
    }, e => {
      if (!active) return;
      reportError('GeneratedDocuments:list', e);
      setRead({ status: 'error', items: [], error: e?.message || 'Generated documents are unreadable. Try again.' });
    });
    return () => { active = false; };
  }, [attempt]);

  if (read.status === 'pending') return null;
  const header = n => <h3 className="mb-2 text-sm font-extrabold">Generated by the platform{n != null && <span className={`font-medium ${muted}`}> · {n}</span>}</h3>;
  if (read.status === 'error') {
    if (layer !== 'all' || state !== 'all') return null;
    return <section data-testid="generated-group">
      {header(null)}
      <div role="alert" className={`${card} flex flex-wrap items-center gap-2 p-2.5 text-xs dark:border-[#2a2733] dark:bg-[#18161f]`}>
        <span>{read.error}</span>
        <button type="button" className={roseLink} onClick={() => { setRead({ status: 'pending', items: [], error: '' }); setAttempt(n => n + 1); }}>Retry</button>
      </div>
    </section>;
  }
  const items = visibleGenerated(read.items, { q, layer, state });
  if (!items.length) return null;
  return <section data-testid="generated-group">
    {header(items.length)}
    <div className="grid gap-2.5" style={{ gridTemplateColumns: 'repeat(4, minmax(0, 1fr))' }}>
      {items.map(item => <GeneratedCard key={item.key} item={item} thumbs={thumbs} onOpen={onOpen} />)}
    </div>
  </section>;
}
